import assert from 'node:assert/strict';
import { after, before, describe, it } from 'node:test';
import { api, startTestServer, type TestServer } from './helpers.ts';

const recipient = { name: 'Anna Huber', street: 'Mariahilfer Straße 1', zip: '1060', city: 'Wien', country: 'AT' };
const N = 5000;

describe('GET /shipments on a 5k-shipment dataset', () => {
  let srv: TestServer;

  before(async () => {
    srv = await startTestServer();
    for (let i = 0; i < N; i++) {
      srv.store.addShipment(
        { trackingNumber: `T${i}`, carrier: 'DHL', serviceLevel: 'standard', recipient },
        new Date(Date.UTC(2026, 0, 1) + i * 60_000),
      );
    }
  });

  after(async () => {
    await srv.close();
  });

  it('returns the newest shipments first, each with a fresh eta (no caching)', async () => {
    const res = await api(srv.url, 'GET', '/shipments?limit=50');
    assert.equal(res.body.count, 50);
    assert.equal(res.body.items[0].tracking_number, `T${N - 1}`);
    assert.equal(res.body.items[49].tracking_number, `T${N - 50}`);
    for (const item of res.body.items) assert.match(item.eta, /^\d{4}-\d{2}-\d{2}$/);

    // an event after the first call must show up in the next one
    const id = res.body.items[0].id;
    srv.store.addEvent(id, 'delivered');
    const again = await api(srv.url, 'GET', '/shipments?limit=50');
    assert.equal(again.body.items[0].eta, null);
  });

  it('answers within a generous budget (guards against O(n log n) work with slow comparators)', async () => {
    await api(srv.url, 'GET', '/shipments'); // warm up
    const runs = 20;
    const start = performance.now();
    for (let i = 0; i < runs; i++) await api(srv.url, 'GET', '/shipments?limit=500');
    const avg = (performance.now() - start) / runs;
    assert.ok(avg < 100, `average ${avg.toFixed(1)} ms per request, expected < 100 ms`);
  });
});
EOF
